-- Introspection fixture, PostgreSQL flavor of the logical "shop" schema shared by every
-- engine (see meta_sqlite.sql). {shop}, {sales} and {odd} are replaced by unique schema
-- names, so concurrent runs never collide; the test drops them afterwards.
-- Statements end with `;` at the end of a line (dollar-quoted bodies keep theirs inside).

CREATE SCHEMA {shop};
CREATE SCHEMA {sales};
CREATE SCHEMA {odd};
COMMENT ON SCHEMA {shop} IS 'Catalog and orders';

CREATE TYPE {shop}.product_status AS ENUM ('draft', 'active', 'archived');
CREATE DOMAIN {shop}.positive_amount AS numeric(12,2) CHECK (VALUE >= 0);
CREATE TYPE {shop}.money_amount AS (amount numeric(12,2), currency char(3));

CREATE TABLE {shop}.customers (
    id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    email text NOT NULL,
    full_name varchar(200) NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT customers_email_key UNIQUE (email)
);
COMMENT ON TABLE {shop}.customers IS 'People who ordered';
COMMENT ON COLUMN {shop}.customers.email IS 'Lower-cased';
CREATE INDEX customers_lower_email_idx ON {shop}.customers (lower(email));

CREATE TABLE {shop}.products (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sku varchar(32) NOT NULL,
    name text NOT NULL,
    price numeric(10,2) NOT NULL,
    status {shop}.product_status NOT NULL DEFAULT 'draft',
    CONSTRAINT products_sku_key UNIQUE (sku),
    CONSTRAINT products_name_status_key UNIQUE (name, status),
    CONSTRAINT products_price_check CHECK (price >= 0)
);

CREATE TABLE {shop}.orders (
    id serial PRIMARY KEY,
    customer_id integer NOT NULL,
    subtotal {shop}.positive_amount NOT NULL,
    shipping numeric(12,2) NOT NULL DEFAULT 0,
    total numeric(12,2) GENERATED ALWAYS AS (subtotal + shipping) STORED,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT orders_customer_fk FOREIGN KEY (customer_id)
        REFERENCES {shop}.customers (id) ON DELETE CASCADE
);
CREATE INDEX orders_created_at_idx ON {shop}.orders (created_at DESC) WHERE total > 0;

CREATE TABLE {shop}.order_items (
    order_id integer NOT NULL,
    product_id integer NOT NULL,
    quantity integer NOT NULL CHECK (quantity > 0),
    PRIMARY KEY (order_id, product_id),
    CONSTRAINT order_items_order_fk FOREIGN KEY (order_id)
        REFERENCES {shop}.orders (id) ON DELETE CASCADE,
    CONSTRAINT order_items_product_fk FOREIGN KEY (product_id)
        REFERENCES {shop}.products (id) ON UPDATE CASCADE ON DELETE RESTRICT
);

CREATE TABLE {odd}."Odd ""Table""" (
    "Id" integer PRIMARY KEY,
    "Select" text,
    "col with space" text
);

CREATE SEQUENCE {sales}.invoice_number_seq START 1000;

CREATE TABLE {sales}.invoices (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    number bigint NOT NULL DEFAULT nextval('{sales}.invoice_number_seq'),
    order_id integer NOT NULL,
    issued_at date NOT NULL DEFAULT CURRENT_DATE,
    CONSTRAINT invoices_order_fk FOREIGN KEY (order_id) REFERENCES {shop}.orders (id)
);

CREATE VIEW {shop}.customer_orders AS
SELECT o.id AS order_id, c.email, o.total
FROM {shop}.orders o JOIN {shop}.customers c ON c.id = o.customer_id;

CREATE MATERIALIZED VIEW {sales}.daily_sales AS
SELECT created_at::date AS day, sum(total) AS revenue FROM {shop}.orders GROUP BY 1;

CREATE FUNCTION {shop}.order_total(p_order_id integer) RETURNS numeric
LANGUAGE sql STABLE AS $$ SELECT total FROM {shop}.orders WHERE id = p_order_id; $$;
CREATE FUNCTION {shop}.order_total(p_order_id integer, p_with_shipping boolean) RETURNS numeric
LANGUAGE sql STABLE AS $$ SELECT 0::numeric; $$;
COMMENT ON FUNCTION {shop}.order_total(integer) IS 'Total of an order';

CREATE PROCEDURE {sales}.archive_invoices(p_before date)
LANGUAGE plpgsql AS $$
BEGIN
    DELETE FROM {sales}.invoices WHERE issued_at < p_before;
END
$$;

CREATE FUNCTION {shop}.touch() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    NEW.created_at := now();
    RETURN NEW;
END
$$;
CREATE TRIGGER orders_touch BEFORE UPDATE ON {shop}.orders
FOR EACH ROW EXECUTE FUNCTION {shop}.touch();
